∀ {h j σ Λ C : ℝ} {P0 : ℝ → ℝ} {d : NavierStokes.NaturalAxisCoefficients.AnalyticInputs h j σ P0}
  {F : NavierStokes.NaturalProfile.ProfileFamily d Λ C} {hΛ : 0 < Λ}
  {hsmall : NavierStokes.NaturalAxisData.SmallParameters h j} {hP0 : ContDiff ℝ (↑⊤) P0}
  (r : NavierStokes.ActivationContinuation.RampParameters F hΛ hsmall hP0) {p : NavierStokes.ProfileHistories.Point},
  p.2 ∈ Set.Icc (-1) 1 →
    r.holdRadius ≤ p.1 →
      NavierStokes.ActivationContinuation.shearA r.profiles p = 4 / 5 ∧
        NavierStokes.ActivationContinuation.shearB r.profiles p = 0
